// NewRequestTemporaryAccessPayload builds a identity service
// request_temporary_access endpoint payload.
func NewRequestTemporaryAccessPayload(body *RequestTemporaryAccessRequestBody, cookie string) *identity.RequestTemporaryAccessPayload {
	v := &identity.RequestTemporaryAccessPayload{
		Minutes: *body.Minutes,
		Reason:  *body.Reason,
	}
	v.Grants = make([]*identity.PermissionGrant, len(body.Grants))
	for i, val := range body.Grants {
		if val == nil {
			v.Grants[i] = nil
			continue
		}
		v.Grants[i] = unmarshalPermissionGrantRequestBodyToIdentityPermissionGrant(val)
	}
	v.Cookie = cookie

	return v
}

