// ValidateRequestTemporaryAccessRequestBody runs the validations defined on
// RequestTemporaryAccessRequestBody
func ValidateRequestTemporaryAccessRequestBody(body *RequestTemporaryAccessRequestBody) (err error) {
	if body.Grants == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("grants", "body"))
	}
	if body.Minutes == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("minutes", "body"))
	}
	if body.Reason == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("reason", "body"))
	}
	if len(body.Grants) > 30 {
		err = goa.MergeErrors(err, goa.InvalidLengthError("body.grants", body.Grants, len(body.Grants), 30, false))
	}
	for _, e := range body.Grants {
		if e != nil {
			if err2 := validatePermissionGrantRequestBody(e, "body.grants[*]"); err2 != nil {
				err = goa.MergeErrors(err, err2)
			}
		}
	}
	if body.Minutes != nil {
		if !(*body.Minutes == 30 || *body.Minutes == 60 || *body.Minutes == 120 || *body.Minutes == 240 || *body.Minutes == 480 || *body.Minutes == 1440 || *body.Minutes == 4320 || *body.Minutes == 10080) {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.minutes", *body.Minutes, []any{30, 60, 120, 240, 480, 1440, 4320, 10080}))
		}
	}
	if body.Reason != nil {
		if utf8.RuneCountInString(*body.Reason) < 5 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.reason", *body.Reason, utf8.RuneCountInString(*body.Reason), 5, true))
		}
		if utf8.RuneCountInString(*body.Reason) > 500 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.reason", *body.Reason, utf8.RuneCountInString(*body.Reason), 500, false))
		}
	}
	return
}

